      --bg: #070B14; --surface: #0F172A; --surface-hover: #1E293B;
      --border: rgba(255,255,255,0.06);
      --text: #EDEDED; --text-secondary: #94A3B8;
      --accent: #3B82F6; --accent-secondary: #8B5CF6;
      --positive: #10B981; --negative: #F43F5E; --warning: #F59E0B;
      --openai: #10B981; --anthropic: #F59E0B; --google: #6366F1; --deepseek: #06B6D4;
      --bar-track: rgba(255,255,255,0.04);
      --hero-glow: radial-gradient(ellipse at 50% -10%, rgba(59,130,246,0.12) 0%, transparent 55%);
      --dot-color: rgba(255,255,255,0.025);
    }
    html.theme-light {
      --bg: #F8FAFC; --surface: #FFFFFF; --surface-hover: #F1F5F9;
      --border: rgba(0,0,0,0.08);
      --text: #0F172A; --text-secondary: #64748B;
      --accent: #2563EB; --accent-secondary: #7C3AED;
      --positive: #059669; --negative: #E11D48; --warning: #D97706;
      --openai: #059669; --anthropic: #D97706; --google: #4F46E5; --deepseek: #0891B2;
      --bar-track: rgba(0,0,0,0.05);
      --hero-glow: radial-gradient(ellipse at 50% -10%, rgba(37,99,235,0.06) 0%, transparent 55%);
      --dot-color: rgba(0,0,0,0.03);
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: var(--bg); color: var(--text);
      line-height: 1.5; -webkit-font-smoothing: antialiased;
      letter-spacing: -0.01em; font-feature-settings: 'cv11', 'ss01';
      transition: background 0.3s, color 0.3s;
      width: 1080px; height: 1920px; overflow: hidden;
      display: flex; flex-direction: column;
      position: relative;
    }
    body::before {
      content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
      background: var(--hero-glow); pointer-events: none; z-index: 0;
    }
    body::after {
      content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
      background-image: radial-gradient(var(--dot-color) 1px, transparent 1px);
      background-size: 28px 28px; pointer-events: none; z-index: 0;
    }

    h1,h2,h3,h4,h5,h6 { color: var(--text); letter-spacing: -0.03em; line-height: 1.08; text-wrap: balance; }
    h1 { font-weight: 700; } h2 { font-weight: 600; } h3 { font-weight: 500; }
    body, p, li, td, th, span, label { font-weight: 400; }
    p,li,td,th,span,label { color: var(--text); }
    .text-secondary { color: var(--text-secondary); }

    .card { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 24px; transition: box-shadow 0.2s ease; }
    .card:hover { box-shadow: 0 0 0 1px var(--border), 0 8px 16px rgba(0,0,0,0.08); }

    /* ===== ANIMATIONS ===== */
    @keyframes fadeInUp { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
    @keyframes slideInLeft { from { opacity: 0; transform: translateX(-40px); } to { opacity: 1; transform: translateX(0); } }
    @keyframes slideInRight { from { opacity: 0; transform: translateX(40px); } to { opacity: 1; transform: translateX(0); } }
    @keyframes barGrow { from { transform: scaleX(0); } to { transform: scaleX(1); } }
    @keyframes countUp { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
    .animate { animation: fadeInUp 0.6s ease-out both; }
    .animate.delay-1 { animation-delay: 0.1s; }
    .animate.delay-2 { animation-delay: 0.2s; }
    .animate.delay-3 { animation-delay: 0.3s; }
    .animate.delay-4 { animation-delay: 0.4s; }
    .animate.delay-5 { animation-delay: 0.5s; }
    .animate.delay-6 { animation-delay: 0.6s; }

    .reveal { opacity: 0; transform: translateY(24px); transition: opacity 0.6s ease, transform 0.6s ease; }
    .reveal.visible { opacity: 1; transform: translateY(0); }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
      .reveal { opacity: 1; transform: none; }
    }

    /* ===== PRINT ===== */
    @media print {
      body { background: white !important; color: black !important; width: auto; height: auto; overflow: visible; }
      .viz-menu { display: none; }
      .card { break-inside: avoid; border: 1px solid #ddd; box-shadow: none; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }
    @page { margin: 1in; @bottom-center { content: "Page " counter(page); font-size: 9pt; color: #666; } }

    /* ===== MENU ===== */
    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px); transition: all 0.2s;
    }
    .viz-menu-toggle:hover { background: var(--surface-hover); }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 200px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s; backdrop-filter: blur(16px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    /* ===== POSTER-SPECIFIC STYLES ===== */
    .poster-header {
      position: relative; z-index: 1;
      padding: 32px 52px 16px;
      flex: 0 0 auto;
    }
    .header-label {
      font-size: 13px; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase;
      color: var(--accent); margin-bottom: 6px;
    }
    .header-title {
      font-size: 46px; font-weight: 700; letter-spacing: -0.03em; line-height: 1.05;
      margin-bottom: 10px;
    }
    .header-subtitle {
      font-size: 15px; color: var(--text-secondary); line-height: 1.5; max-width: 720px;
    }

    .hero-metrics {
      display: flex; gap: 16px; margin-top: 22px;
    }
    .metric-badge {
      flex: 1; background: var(--surface); border: 1px solid var(--border);
      border-radius: 10px; padding: 14px 18px;
      display: flex; flex-direction: column; gap: 2px;
    }
    .metric-value {
      font-size: 32px; font-weight: 700; color: var(--accent);
      letter-spacing: -0.03em; line-height: 1.1;
    }
    .metric-label {
      font-size: 12px; color: var(--text-secondary); text-transform: uppercase;
      letter-spacing: 0.06em; font-weight: 500;
    }

    .family-legend {
      display: flex; gap: 20px; margin-top: 16px; align-items: center;
    }
    .legend-item {
      display: flex; align-items: center; gap: 6px; font-size: 12px;
      color: var(--text-secondary); font-weight: 500;
    }
    .legend-dot {
      width: 10px; height: 10px; border-radius: 50%;
    }

    /* Ranking Section */
    .ranking-section {
      position: relative; z-index: 1;
      padding: 8px 52px;
      flex: 1 1 0; min-height: 0;
      display: flex; flex-direction: column;
    }
    .section-title {
      font-size: 13px; font-weight: 600; letter-spacing: 0.1em;
      text-transform: uppercase; color: var(--text-secondary);
      margin-bottom: 8px; padding-bottom: 6px;
      border-bottom: 1px solid var(--border);
    }
    .ranking-cols {
      display: flex; align-items: center; gap: 0;
      font-size: 11px; color: var(--text-secondary); text-transform: uppercase;
      letter-spacing: 0.06em; font-weight: 500;
      padding: 0 0 6px 0; margin-bottom: 2px;
    }
    .col-rank { width: 32px; text-align: center; }
    .col-name { width: 190px; padding-left: 8px; }
    .col-bar { flex: 1; }
    .col-accuracy { width: 56px; text-align: right; }
    .col-cost { width: 64px; text-align: right; }
    .col-format { width: 52px; text-align: right; }

    .ranking-rows { flex: 1; display: flex; flex-direction: column; gap: 3px; overflow: hidden; }

    .model-row {
      display: flex; align-items: center; gap: 0;
      height: 38px; border-radius: 6px;
      transition: background 0.15s;
    }
    .model-row:hover { background: var(--surface); }
    .model-rank {
      width: 32px; text-align: center; font-size: 14px;
      font-weight: 600; color: var(--text-secondary);
      font-variant-numeric: tabular-nums;
    }
    .model-row:nth-child(1) .model-rank,
    .model-row:nth-child(2) .model-rank,
    .model-row:nth-child(3) .model-rank { color: var(--accent); }
    .model-name {
      width: 190px; padding-left: 8px; font-size: 14px;
      font-weight: 500; white-space: nowrap; overflow: hidden;
      text-overflow: ellipsis;
    }
    .model-bar-track {
      flex: 1; height: 20px; background: var(--bar-track);
      border-radius: 4px; overflow: hidden; position: relative;
    }
    .model-bar-fill {
      height: 100%; border-radius: 4px;
      transform-origin: left; animation: barGrow 0.8s ease-out both;
      position: relative;
    }
    .model-bar-fill::after {
      content: ''; position: absolute; top: 0; right: 0; bottom: 0; width: 40%;
      background: linear-gradient(90deg, transparent, rgba(255,255,255,0.08));
      border-radius: 0 4px 4px 0;
    }
    .model-accuracy {
      width: 56px; text-align: right; font-size: 14px;
      font-weight: 700; padding-right: 8px;
      font-variant-numeric: tabular-nums;
    }
    .model-cost {
      width: 64px; text-align: right; font-size: 12px;
      color: var(--text-secondary); padding-right: 6px;
      font-variant-numeric: tabular-nums;
    }
    .model-format {
      width: 52px; text-align: right; font-size: 11px;
      color: var(--text-secondary); padding-right: 2px;
      font-variant-numeric: tabular-nums;
    }
    .format-tag {
      display: inline-block; font-size: 9px; padding: 1px 4px;
      border-radius: 3px; font-weight: 600; letter-spacing: 0.03em;
      margin-right: 2px; vertical-align: middle;
    }
    .format-tag.diff { background: rgba(59,130,246,0.15); color: var(--accent); }
    .format-tag.diff-fenced { background: rgba(139,92,246,0.15); color: var(--accent-secondary); }

    /* Charts Section */
    .charts-section {
      position: relative; z-index: 1;
      padding: 8px 52px;
      flex: 0 0 auto;
    }
    .chart-wrapper {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 24px 28px 16px;
    }
    .chart-wrapper canvas { width: 100% !important; }

    /* Bottom Section */
    .bottom-section {
      position: relative; z-index: 1;
      padding: 8px 52px;
      flex: 0 0 auto;
      display: flex; gap: 20px;
    }
    .format-panel {
      flex: 1; display: flex; flex-direction: column;
    }
    .format-chart-wrap {
      flex: 1; background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 16px 20px 8px;
      min-height: 300px;
    }
    .takeaways-panel {
      flex: 1; display: flex; flex-direction: column;
    }
    .takeaway-grid {
      display: flex; flex-direction: column; gap: 10px; flex: 1;
    }
    .takeaway-card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 10px; padding: 14px 16px;
      display: flex; gap: 12px; align-items: flex-start;
      flex: 1;
    }
    .takeaway-icon {
      width: 32px; height: 32px; border-radius: 8px;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0; font-size: 16px;
    }
    .takeaway-icon.trophy { background: rgba(16,185,129,0.12); color: var(--positive); }
    .takeaway-icon.shield { background: rgba(245,158,11,0.12); color: var(--anthropic); }
    .takeaway-icon.dollar { background: rgba(6,182,212,0.12); color: var(--deepseek); }
    .takeaway-icon.format { background: rgba(99,102,241,0.12); color: var(--google); }
    .takeaway-text {
      font-size: 13px; line-height: 1.45; color: var(--text-secondary);
    }
    .takeaway-text strong { color: var(--text); font-weight: 600; }

    /* Footer */
    .poster-footer {
      position: relative; z-index: 1;
      padding: 14px 52px 28px;
      flex: 0 0 auto;
      display: flex; justify-content: space-between; align-items: center;
    }
    .footer-source {
      font-size: 11px; color: var(--text-secondary);
      letter-spacing: 0.02em;
    }
    .footer-badge {
      font-size: 10px; color: var(--text-secondary);
      background: var(--surface); border: 1px solid var(--border);
      padding: 4px 10px; border-radius: 6px;
      letter-spacing: 0.04em; text-transform: uppercase; font-weight: 500;
    }

    @media (max-width: 375px) { body { overflow-x: hidden; } }
  </style>
</head>
