    function getFamilyColor(family) {
      var s = getComputedStyle(document.documentElement);
      return s.getPropertyValue('--' + family).trim();
    }
    function getFamilyColorAlpha(family, alpha) {
      var hex = getFamilyColor(family);
      var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
      return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
    }

    // === BUILD RANKING ===
    function buildRanking() {
      var container = document.getElementById('rankingRows');
      if (!container) return;
      var html = '';
      modelData.forEach(function(m, i) {
        var barWidth = (m.accuracy / maxAccuracy * 100).toFixed(1);
        var delay = 0.05 * i;
        html += '<div class="model-row" style="animation:fadeInUp 0.4s ease-out ' + delay + 's both">';
        html += '  <span class="model-rank">' + m.rank + '</span>';
        html += '  <span class="model-name" style="color:' + getFamilyColor(m.family) + '">' + m.name + '</span>';
        html += '  <div class="model-bar-track">';
        html += '    <div class="model-bar-fill" style="width:' + barWidth + '%;background:' + getFamilyColorAlpha(m.family, 0.7) + ';border:1px solid ' + getFamilyColorAlpha(m.family, 0.9) + '"></div>';
        html += '  </div>';
        html += '  <span class="model-accuracy">' + m.accuracy.toFixed(1) + '%</span>';
        html += '  <span class="model-cost">$' + m.cost.toFixed(2) + '</span>';
        html += '  <span class="model-format"><span class="format-tag ' + m.editFormat + '">' + m.editFormat + '</span> ' + m.format.toFixed(1) + '%</span>';
        html += '</div>';
      });
      container.innerHTML = html;
    }

    // === CHART MANAGER ===
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
