      destroyAll: function() {
        this.charts.forEach(function(chart) { try { chart.destroy(); } catch(e) {} });
        this.charts.clear();
      }
    };

    // === BUILD CHARTS ===
    var chartsBuilt = false;

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;

      var isDark = document.documentElement.classList.contains('theme-dark');
      var textColor = isDark ? '#EDEDED' : '#0F172A';
      var textSecondaryColor = isDark ? '#94A3B8' : '#64748B';
      var gridColor = isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.06)';

      // === SCATTER CHART ===
      var families = ['openai', 'anthropic', 'google', 'deepseek'];
      var familyLabels = { openai: 'OpenAI', anthropic: 'Anthropic', google: 'Google', deepseek: 'DeepSeek' };
      var scatterDatasets = {};

      modelData.forEach(function(m) {
        if (!scatterDatasets[m.family]) {
          scatterDatasets[m.family] = {
            label: familyLabels[m.family],
            data: [],
            backgroundColor: getFamilyColorAlpha(m.family, 0.75),
            borderColor: getFamilyColor(m.family),
            borderWidth: 2,
            pointRadius: 8,
            pointHoverRadius: 11,
            pointStyle: 'circle'
          };
        }
        scatterDatasets[m.family].data.push({ x: m.cost, y: m.accuracy, name: m.name });
      });

      ChartManager.safeInit('scatterChart', {
        type: 'scatter',
        data: { datasets: families.map(function(f) { return scatterDatasets[f]; }) },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { top: 10, right: 16, bottom: 4, left: 4 } },
          plugins: {
            tooltip: {
              enabled: true, padding: 12, cornerRadius: 8,
              titleFont: { size: 13, family: 'Inter' }, bodyFont: { size: 12, family: 'Inter' },
              callbacks: {
                title: function(ctx) { return ctx[0].raw.name; },
                label: function(ctx) { return ctx.raw.y + '% accuracy at $' + ctx.raw.x.toFixed(2); }
              }
            },
            legend: {
              position: 'top', align: 'end',
              labels: { color: textSecondaryColor, font: { family: 'Inter', size: 12 }, padding: 14, usePointStyle: true, pointStyleWidth: 10 }
            }
          },
          scales: {
            x: {
              title: { display: true, text: 'Cost per Run ($)', color: textSecondaryColor, font: { size: 12, family: 'Inter' } },
              ticks: { color: textSecondaryColor, font: { size: 11, family: 'Inter' }, callback: function(v) { return '$' + v; } },
              grid: { color: gridColor, drawBorder: false },
              min: 0, max: 32
            },
            y: {
              title: { display: true, text: 'Accuracy (%)', color: textSecondaryColor, font: { size: 12, family: 'Inter' } },
              ticks: { color: textSecondaryColor, font: { size: 11, family: 'Inter' }, callback: function(v) { return v + '%'; } },
              grid: { color: gridColor, drawBorder: false },
              min: 68, max: 92
            }
          }
        }
      });

      // === FORMAT COMPLIANCE CHART ===
      var formatColors = modelData.map(function(m) {
        return m.editFormat === 'diff-fenced'
