          : (isDark ? 'rgba(59,130,246,0.7)' : 'rgba(37,99,235,0.7)');
      });
      var formatBorders = modelData.map(function(m) {
        return m.editFormat === 'diff-fenced'
          ? (isDark ? '#8B5CF6' : '#7C3AED')
          : (isDark ? '#3B82F6' : '#2563EB');
      });

      ChartManager.safeInit('formatChart', {
        type: 'bar',
        data: {
          labels: modelData.map(function(m) { return m.name; }),
          datasets: [{
            label: 'Format Compliance',
            data: modelData.map(function(m) { return m.format; }),
            backgroundColor: formatColors,
            borderColor: formatBorders,
            borderWidth: 1,
            borderRadius: 3,
            barThickness: 14
          }]
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { top: 4, right: 12, bottom: 4, left: 0 } },
          plugins: {
            tooltip: {
              enabled: true, padding: 10, cornerRadius: 8,
              titleFont: { size: 12, family: 'Inter' }, bodyFont: { size: 12, family: 'Inter' },
              callbacks: {
                label: function(ctx) {
                  var m = modelData[ctx.dataIndex];
                  return m.format.toFixed(1) + '% (' + m.editFormat + ')';
                }
              }
            },
            legend: { display: false }
          },
          scales: {
            x: {
              min: 82, max: 100,
              ticks: { color: textSecondaryColor, font: { size: 10, family: 'Inter' }, callback: function(v) { return v + '%'; }, maxTicksLimit: 5 },
              grid: { color: gridColor, drawBorder: false }
            },
            y: {
              ticks: { color: textSecondaryColor, font: { size: 10, family: 'Inter' }, mirror: false },
              grid: { display: false }
            }
          }
        }
      });

      chartsBuilt = true;
    }

    function onThemeChange() {
      chartsBuilt = false;
      ChartManager.destroyAll();
      buildRanking();
      setTimeout(buildCharts, 100);
    }

    // === MENU ===
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === THEME ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === SCROLL REVEAL ===
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    // === NUMBER COUNTER ===
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count), suffix = el.dataset.suffix || '';
        var decimals = parseInt(el.dataset.decimals) || 0;
        var start = performance.now(), duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
