      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    // === INIT ===
    document.addEventListener('DOMContentLoaded', function() {
      buildRanking();
      buildCharts();
      animateCounters();
    });
  </script>
</body>
